\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tractatus magistri Johannis de Gersona doctoris eximij de remedijs contra pusillanimitatem, scrupulositatem deceptorias, inimici consolaciones et subtiles eius temptacionibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 \endash  Qui pusillanimis est et pauidus ... \endash  ... quia complacuit patri vestro celesti dare vobis regnum in secula seculorum Amen. \endash  Visum est aliquibus quod non Gerson sed alter auctor sit huius tractatus ... \endash  ... pocius nomine auctoris.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Gerson, \u338 \'8cuvres compl\u232 \'e8tes, Bd. X, S. 374-385, Nr. 537. \endash  \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20 , Incipits, Nr. 4624.}

