\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 110ra-229vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Theodericus de Apolda}}\plain \f1\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Liber de vita et obitu et miraculis sancti Dominici, et de ordine quem instituit}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 (110ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Mandatum magistri ordinis Munionis ad fratrem Theodericum de Apoldia\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 Dilecto sibi in Christo fratri Theoderico de Apoldia Erfordensis provincia ...\plain \f1\lang1033\fs24\cf1  \endash  (110rb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Epistola fratris Theoderici ad magistrum ordinis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 Patri filiorum amabili Nycolao magistro fratrum predicatorum\plain \f1\lang1033\fs24\cf1  ... \endash  (112ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit prohemium in legendam sancti patris Dominici\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 Multipharie multisque modis olim deus electos ad eternum\plain \f1\lang1033\fs24\cf1  ... \endash  (112vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit prologus in vitam sancti Dominici\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 Karitas de corde puro\plain \f1\lang1033\fs24\cf1  ... \endash  (113vb-114ra) Kapitel\u252 \'fcbersicht.  \endash  (114ra) Vita: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De pietate et honestate parentum sancti Dominici et ortu eius celitus ostenso\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 In nomine patris ...  Dominicus humilis seruus Ihesu Christi segregatus\plain \f1\lang1033\fs24\cf1  ... \endash  ... (229vb) \plain \f1\i\lang1033\fs24\cf1 dulcedo verbis non exprimitur nec depingitur attramento\plain \f1\lang1033\fs24\cf1  \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit legenda sancti dominici confessoris, institutoris ordinis predicatorum\u8249 \'8b \plain \f1\lang1033\fs24\cf1 \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Scriptus est liber iste per quendam fratrem Sigismundum\plain \f1\lang1033\fs24\cf1  (hinzugef\u252 \'fcgt: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Schretinger\u8249 \'8b) ad honorem sancti Quirini regis er martiris et aliorum patranorum\plain \f1\lang1033\fs24\cf1  (!) \plain \f1\i\lang1033\fs24\cf1 eiusdem monasterij sancti Quirini anno domini 1466\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\lang1033\fs24\cf1 . \plain \f1\i\lang1033\fs24\cf1 Deo gracias\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Est quoddam sine p cui seruit noxque diesque\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 (Walther, Initia, Nr. 5829)\u8249 \'8b \endash  229ar-229bv leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Ed.: Acta SS Aug. I, Antwerpen 1733, S. 562-632. \endash  Lit.; BHL 2226; \plain \f1\scaps\lang1033\fs20 Kaepelli,\plain \f1\lang1033\fs20  Nr. 3677.}

