\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 75r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Georg von Peuerbach}}\plain \f1\b\lang1033\fs24\cf1 : Prologus in IV partem Rhetoricae ad Herennium
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\cf1 Non sum autem dubius generose comes et viri praestantissimi \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 vestris enim inseruire comodis est mihi periocundum etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Einf\u252 \'fchrung in Teil IV der Rhetorica ad Herennium im Rahmen einer Wiener Universit\u228 \'e4tsvorlesung 1457/1458. Edition: Karl Gro\u223 \'dfmann, Eine Ansprache Georgs von Peuerbach an seine H\u246 \'f6rer, in MI\u214 \'d6G 42 (1927), S. 359-361, unter Verwendung dieser Hs.}

