\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipiunt extravagancia quae ad superiora Anthonii exempla \plain \f1\lang1033\fs24\cf1 \u8230 \'85\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Philippus dux Burgundie Barbantie episcopo \plain \f1\lang1033\fs24\cf1 (!)\plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 vale praeceptor obseruandissime.
