\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 (24r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secundum Matheum. Omelia beati Iohannis episcopi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Cum transiret Ihesus \plain \f1\lang1033\fs24\cf1 ... (Mt 9,9). \plain \f1\i\lang1033\fs24\cf1 Omnibus peccatoribus in se credentibus salutem dominus donaturus \plain \f1\lang1033\fs24\cf1 ... \endash  (26r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo sancti Augustini episcopi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Admonent nos eloquia diuina quae lecta sunt \plain \f1\lang1033\fs24\cf1 ... \endash  (30r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo sancti Maximi de martiribus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 De sancto Ypolito. \endash  Recte ac ex debito ecclesie\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 beatorum martyrum celebrant insignia \plain \f1\lang1033\fs24\cf1 ... \endash  ... (137v) \plain \f1\i\lang1033\fs24\cf1 In dedicacione ecclesie sermo sancti Augustini. 1\plain \f1\i\super\lang1033\fs24\cf1 a\plain \f1\i\lang1033\fs24\cf1  Recte festa ecclesie colunt \plain \f1\lang1033\fs24\cf1 ... \endash  51r-52v, 87r-v, 102v, 113v-114v, 124r-126v, 138r-139r leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Sammlung von Sermones und Predigtnotizen, h\u228 \'e4ufig nur skizziert und bruchst\u252 \'fcckhaft. Hier zitiert: Augustinus, Sermo 259, PL 38, 1196. \endash  Augustinus, Sermo 65, PL 38, 426. \endash  Ps.-Maximus Tauriensis, Sermo de martyribus, PL 57, 707-710. \endash  Augustinus, Sermo 231, PL 39, 2171.}

