\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 128r-139v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Hermannus de Schildis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Speculum manuale sacerdotum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit speculum clarum nobile et preciosum ipsorum sacerdotum fratris Hermanni de Saldiz \plain \f1\lang1033\fs24 [korr. aus Scildis]\plain \f1\i\lang1033\fs24  ordinis fratrum heremitarum sancti Augustini \plain \f1\lang1033\fs24 ...\u8249 \'8b \plain \f1\i\lang1033\fs24 Uenerabili in Christo patri ac domino ... Gloriosus doctor Iohannes Crisostomus 3\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  libro de sacerdotali officio loquens \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 in repertorio aureo eodem tytulo circa finem. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Deo gracias\plain \f1\lang1033\fs24 \u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Druck: GW 12295-12301. \endash  Lit.: Zumkeller, Manuskripte, Nr. 54k, Hs. genannt. \endash  Ders., Schrifttum und Lehre des Hermann von Schildesche O.E.S.A. (\u8224 \'86). W\u252 \'fcrzburg 1959 (Cassiciacum 15), S. 43-45. \endash  Ders., in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 3 (1981), Sp. 1111.}

