\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 210v-220v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Manuductio ad confessionem generalem}}\plain \f1\b\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Manuductio quedam breuis quomodo quisque debeat se recolligere ad confessionem generalem faciendam. Et primo de decem praeceptis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Circa primum confessurus multis modis infra positis habet cognoscere peccatum suum \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 qui demones inuocant qui fedus cum eis aut pacta fecerint. \plain \f1\lang1033\fs24 \endash  Darunter Nota zur Exkommunikation.\plain \f1\i\lang1033\fs24  }

