\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ad expellendum demones iste sunt varissime oraciones et coniuraciones \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Ante altare presbyter ligans obsessum legat ewangelia sequencia\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Liber generacionis Ihesu Christi \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Expelle quaesumus domine ab hoc famulo N. omnem infestacionem \plain \f1\lang1033\fs24\cf1 ... \endash  59r-51v leer.}

