\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Tractatus artis memoratiue. \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 Pro aggressu huius operis postulandum est a summo opifice \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 acomodasse impignorasse. \plain \f1\lang1033\fs24\cf1 Darunter Nota zur ars memorandi. \endash  47r, 48v-54v leer. \endash 55ra-55va siehe 42ra. \endash  55vb-56v leer bis auf Federproben.
