\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 8r-360r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermones dominicales de tempore et sanctis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (8r) \plain \f1\i\lang1033\fs24\cf1 Dominica prima aduentus domini. \endash  \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Benedictus qui venit \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b (Mt 21,9). \plain \f1\i\lang1033\fs24\cf1 Istud tempus charissimi \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 vocatur aduentus domini quia secundum quatuor dominicas \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (16r) \plain \f1\i\lang1033\fs24\cf1 Dominica 2\plain \f1\i\super\lang1033\fs24\cf1 a\plain \f1\i\lang1033\fs24\cf1  aduentus domini. \endash  \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Erunt signa \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b (Lc 21,25). \plain \f1\i\lang1033\fs24\cf1 Sancta mater ecclesia sicut pia et sapiens mater omnes fideles \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (24r) \plain \f1\i\lang1033\fs24\cf1 Dominica 3\plain \f1\i\super\lang1033\fs24\cf1 a\plain \f1\i\lang1033\fs24\cf1  aduentus domini. \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 Cum audisset Iohannes \plain \f1\lang1033\fs24\cf1 ... (Mt 11,2). \plain \f1\i\lang1033\fs24\cf1 In hac tertia dominica aduentus recolitur Christi \plain \f1\lang1033\fs24\cf1 [adventus] \plain \f1\i\lang1033\fs24\cf1 ad limbum \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\super\lang1033\fs24\cf1 46\plain \f1\lang1033\fs24\cf1 (348r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In festo sancti Laurencii martiris ...\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 ... nisi granum frumentis \plain \f1\lang1033\fs24\cf1 ... (Io 12,24) ... \plain \f1\i\lang1033\fs24\cf1 Si quis vult \plain \f1\lang1033\fs24\cf1 ... (Mt 16,24). \plain \f1\i\lang1033\fs24\cf1 Christus huius sancti Laurentii\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 martiris imitantis eum in morte sua in verbis istis triumphum exprimens \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 47\plain \f1\lang1033\fs24\cf1 (356r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Simonis et Iude\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ecce quam bonum \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b (Ps 132,1). \plain \f1\i\lang1033\fs24\cf1 Sancta mater ecclesia solemnizat nobis festiuitatem sanctorum apostolorum Symonis et Iude \plain \f1\lang1033\fs24\cf1 ... \endash  360v-368v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Sammlung von 47 Sermones verschiedener Verfasser. \endash  1 und 3 von Hugo de Prato Florido (GND 100946488), Druck: GW 13567-13577. \endash  Sermo 46 von Bernoldus Caesariensis (GND 102424640), ediert in Patrick Monjou, Comment pr\u234 \'eacher \u224 \'e0 la fin du Moyen Age? Tome 2: Le manuel du vulgarisation de Bernold de Kaisheim. Domuni-Press 2021, Nr. 143. \endash  Lit.: Schneyer, Wegweiser, S. 55 (zu 1, diese Hs. zitiert) und 260 (zu 2).}

