\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 1r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Angelus Politianus}}\plain \f1\b\lang1033\fs24\cf1 : Epigrammata in Franciscum Salviatum (1478)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\cf1 Metrum in Saluiatum post memorabile facinus quod 1478 in mayo accidit \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\i\lang1033\fs24\cf1 Quid tam furca doles laqueus cum gestiat \plain \f1\lang1033\fs24\cf1 ... \endash  Dar\u252 \'fcber von anderer Hand nachgetragene Notizen zur lateinischen Metrik (in Fortsetzung der Notizen auf dem VS). \endash  Darunter nachgetragen Stiftungsvermerk (Schwerzenbeck): \plain \f1\i\lang1033\fs24\cf1 Anno domini M\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  cccc\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  lxxxxv\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 [1495] \plain \f1\i\lang1033\fs24\cf1 obiit venerabilis vir dominus Vdalricus Greymolt\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 de Weilhaym et hic obtulit pro fratribus in Tegernsee hunc librum. Anima eius requiescat in luce eterna. Amen. \plain \f1\lang1033\fs24\cf1 \endash  1v leer.
