\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 165r-184v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Hugo de s. Caro}}\plain \f1\b\lang1033\fs24\cf1 : Tractatus super missam sive Speculum ecclesiae
