\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 24r-27v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Conservativum castitatis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\cf1 Conseruatiuum sancte castitatis pro vnoquoque amatore continencie. \endash  Cibus sit frigidus et humidus vt est lactuca \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 inde recipiat et in calceos ponat. Finis. \plain \f1\lang1033\fs24\cf1 \endash  28r-v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Behandelt Ern\u228 \'e4hrung, Schlaf, Bad, Verdauung, Aderlass, Klima und Kleidung.}

