\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 29r-32v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Thomas Finck}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Regimen sanitatis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 Am unteren Blattrand: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Regimen domini doctoris Thome Finckh\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sancta trinitas et Maria et omnes sancti. Regimen compendiosum pro domino et patre nostro reuerendo particulare\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 quomodo sua paternitas debeat se habere in dieta \plain \f1\lang1033\fs24\cf1 ... \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Cibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In primo sua paternitas ita se habeat in cibo. Non comedat neque bibat nisi esuries vel sitis exposcat \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 nichil sic curat egritudinem quam moderata refeccio. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit regimen domini\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 doctoris Thome Finck phisici eximii\plain \f1\lang1033\fs24\cf1 \u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 F\u252 \'fcr einen Tegernseer Abt, vielleicht ebenfalls Heinrich V. Kintzner (1500-1512). \endash  Zum Verfasser siehe Klaus Graf, Thomas Finck. Arzt, Benediktiner in Blaubeuren und Kart\u228 \'e4user in G\u252 \'fcterstein, in: T\u252 \'fcbingen in Lehre und Forschung um 1500, hrsg. von S\u246 \'f6nke Lorenz/Dieter Bauer/Oliver Auge. Sigmaringen 2008 (T\u252 \'fcbinger Bausteine zur Landesgeschichte 9), S. 159-175, Hs. genannt S. 163.}

