\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Remedia Iohannis episcopi de Hagana oculorum medicus \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 praeseruatiua pro domino Hainrico vltimo abbate\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Item aquarum feniculi \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 extrahit materiam peccantem sew spinam. 
