\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 (225v) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Merckt die ler\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Wer den t\u246 \'f6dt nit h\u246 \'f6ch well wegen / der soll hie an all s\u252 \'fcndt leben \plain \f1\lang1033\fs24\cf1 ... \endash  (226r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Dominus Iesus dicit ad hominem\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 O mensch sich an die liebe mein / das kre\u252 \'fccz ich trag von wegen dein \plain \f1\lang1033\fs24\cf1 ... \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 homo respondet\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 O s\u252 \'fcesser got gib mir dein gnad ... \plain \f1\lang1033\fs24\cf1 Daran anschlie\u223 \'dfend (226v) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Vier ding sol der mensch alzeit gedencken\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 die gr\u246 \'f6ss der s\u252 \'fcndt \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1  }

