\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (289va) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit sermo in festiuitate omnium sanctorum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Hodie virgo mater ecclesia per totum orbem spiritu sancto propagante \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (302ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermones de beata virgine Maria legendi sabbatis noctibus ab octaua epiphanie usque ad septuagesimam\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo sancti Augustini episcopi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Natalis est saluatoris. De quo angelus pastoribus dicit \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (302va) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo sancti Augustini episcopi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Nascente enim domino non est ablata sed consecrata \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 4\plain \f1\lang1033\fs24\cf1 (302vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo sancti Augustini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Ducite fideles Christi festiua gaudia \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 5\plain \f1\lang1033\fs24\cf1 (303rb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ex sermone sancti Augustini episcopi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Facta est Maria fenestra celi \plain \f1\lang1033\fs24\cf1 ... \endash  Dazwischen 301rb-v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 1 = u.a. auch in Wolfenb\u252 \'fcttel, HAB, Cod. Guelf. 574 Helmst., 187v, dort Papst Leo I. zugeschrieben. \endash  2 = vgl. Augustinus, Sermo 184, PL 38, 996. \endash  3 = aus Augustinus, Sermo 124, PL 39, 1992. \endash  4 = aus Augustinus, Sermo 119, PL 39, 1982. \endash  5 = aus Augustinus, Sermo 123, PL 39, 1990. }

