\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 221vb-223va   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Miracula Beatae Mariae Virginis}}\plain \f1\b\lang1033\fs24\cf1  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 (221vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Exempla de beata Virgine Maria\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1  (222ra) \plain \f1\i\lang1033\fs24\cf1 Fuit\plain \f1\lang1033\fs24\cf1  (eher \plain \f1\i\lang1033\fs24\cf1 fur\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 quidam qui vocabatur Eppo\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1  (222rb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Aliud exemplum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In ciuitate Papia fuit quidam clericus\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1  (222rb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Aliud exemplum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (222va) \plain \f1\i\lang1033\fs24\cf1 Iymago\plain \f1\lang1033\fs24\cf1  (!) \plain \f1\i\lang1033\fs24\cf1 itaque beatissime Marie ex auro mirifice fabricata\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24\cf1 4\plain \f1\lang1033\fs24\cf1  (222vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Aliud exemplum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Est et alia quedam ecclesia in honore sancti Michael \plain \f1\lang1033\fs24\cf1 ...   \endash  \plain \f1\super\lang1033\fs24\cf1 5\plain \f1\lang1033\fs24\cf1  (223ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Aliud exemplum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Erat vir quidam secularis rurali operi deditus\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash   \plain \f1\super\lang1033\fs24\cf1 6\plain \f1\lang1033\fs24\cf1  (223rb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Aliud exemplum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Sacerdos quidam erat parochie cuiusdam ecclesie deuote seruiens\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash   \u8230 \'85 (223va) \plain \f1\i\lang1033\fs24\cf1 et postea defunctum ad vitam eternam suis meritis introduxit\plain \f1\lang1033\fs24\cf1 .
