\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 297va-299va  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Johannes Schlitpacher}}\plain \f1\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Practica ad officium altaris praeparandi}}
\par \pard\fi0\li0\qj\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\cf1 Pro sacerdotibus missas celebrantibus utilis doctrina. Et intitulatur paruum bonum collectum ex dictis doctorum multorum\plain \f1\lang1033\fs24\cf1 . \plain \f1\i\lang1033\fs24\cf1 \endash  Ante omnia autem scire volo caritatem tuam ...\endash \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 amore sumpturus deum et hominem qui est benedictus in secula Amen \endash  Explicit paruum bonum collectum ex rarijs doctoribus de sacramenti disposicione. \endash  \plain \f1\lang1033\fs24\cf1 299vb leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Zum Autorenvorschlag Johannes Schlitpacher siehe Adolph \plain \f1\scaps\lang1033\fs20 Franz\plain \f1\lang1033\fs20 , Die Messe im deutschen Mittelalter: Beitr\u228 \'e4ge zur Geschichte der Liturgie und des religi\u246 \'f6sen Volkslebens, Freiburg im Breisgau; M\u252 \'fcnchen [u.a.]: Herder, 1902, S. 579f; Parallel\u252 \'fcberlieferung: Wien, \u214 \'d6NB, Cod. 3651, 116a-117b; Melk, Benediktinerstift, Cod. 1776 (412, H 27), 221r-223r; N\u252 \'fcrnberg GNM 4772a, 149r-152r.}

