\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 1ra-350va  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Bartholomaeus von Pisa}}\plain \f1\b\lang1033\fs24\cf1 :\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Summa de casibus conscientiae}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Summa Bartholomei Pisani de casibus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b (1ra) Prolog: \plain \f1\i\lang1033\fs24\cf1 Quoniam, ut ait Gregorius super Eze\plain \f1\lang1033\fs24\cf1 [c]\plain \f1\i\lang1033\fs24\cf1 hielem, nullum omnipotenti Deo\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash   (1va) Text: \plain \f1\i\lang1033\fs24\cf1 Abbas in suo monasterio conferre potest\plain \f1\lang1033\fs24\cf1  \u8230 \'85  \endash  \u8230 \'85 (350va) \plain \f1\i\lang1033\fs24\cf1 alter excedit ipsum in bonis, tunc est inuidia, ut dictum est supra Inuidia\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 F\plain \f1\lang1033\fs24\cf1 . \plain \f1\i\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1  \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Scriptus est hic liber etc. per manum Nicolai Prenner, finitusque in sancti\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 uigilia Udalrici\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 anno etc. Domini 1428\plain \f1\lang1033\fs24\cf1 \u8249 \'8b [1428 Juli 3]. \endash   \plain \f1\i\lang1033\fs24\cf1 Item registrum super hoc opus require in Pisanella et ibi reperies\plain \f1\lang1033\fs24\cf1 .  \endash   350vb leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: GW 3450\endash 3456. Kaeppeli Nr. 436 (Hs. genannt). Schreiber: Nicolaus Prenner, Plebanus in Westerwargaw [Warngau, Lkr. Miesbach?] (Kr\u228 \'e4mer, Scriptores).Von ihm auch: Clm 18256 (von 1429);  Clm 18133, fol. 1-222 (von 1431), beide Hss. aus Tegernsee.}

