\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 44va-164ra  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Jacobus de J\u252 \'fcterbog seu de Paradiso}}\plain \f1\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermones de tempore, de sanctis et de BMV}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (44va) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo magistri Jacobi Carthusiensis de annunciacione sancte Marie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Missus est angelus\plain \f1\lang1033\fs24\cf1  ... (Lc 1,26) \plain \f1\i\lang1033\fs24\cf1 Sicut dulcis cibus\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 palatum dulcorat \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b \endash   \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (48ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ingressus angelus\plain \f1\lang1033\fs24\cf1  ... (Lc 1,28)\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1  Cum humilitate et condigna veneracione aliquid locuturus\plain \f1\lang1033\fs24\cf1  ...  \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (53ra)  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sequitur sermo Carthusiensis de nativitate Domini nostri Ihesu Cristi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Impleti sunt dies\plain \f1\lang1033\fs24\cf1  ... (Lc 2,6-7)\u8249 \'8b  \plain \f1\i\lang1033\fs24\cf1 Postillationibus ewangelistarum intendo supersedere\plain \f1\lang1033\fs24\cf1  ...  \endash  \plain \f1\super\lang1033\fs24\cf1 31\plain \f1\lang1033\fs24\cf1 (156ra)  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In visitacione  beate Virginis Marie sermo Carthusiensis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Exurgens Maria\plain \f1\lang1033\fs24\cf1  ... (Lc 1,39)\u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Scimus quod in conuencione et mul\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1 titudine sapientum\plain \f1\lang1033\fs24\cf1  ...  \endash  \plain \f1\super\lang1033\fs24\cf1 32\plain \f1\lang1033\fs24\cf1 (160vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In purificacione beate Virginis Marie sermo Carthusiensis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b  \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Postquam impleti sunt dies\plain \f1\lang1033\fs24\cf1  ... (Lc 2,22)\u8249 \'8b  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Expeditis satis debiliter sermo\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1 nibus quibusdam\plain \f1\lang1033\fs24\cf1  ... \endash   ... (165ra) \plain \f1\i\lang1033\fs24\cf1 venite, benedicti patris mei. Quod nobis concedat\plain \f1\lang1033\fs24\cf1  ... \plain \f1\i\lang1033\fs24\cf1 Amen etc\plain \f1\lang1033\fs24\cf1 .  \endash   \u8250 \'9b1470\u8249 \'8b  \endash   Nachtrag: \plain \f1\i\lang1033\fs24\cf1 Sequentes sermones duos precedencium sermonum compilator non videtur composuisse
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Drucke: Hain, 9329-*9334 \endash  Lit.: Meier, a.a.O. Nr. 94, S. 76f. \plain \f2\lang1024\fs20 Jakub z Parady\u380 \'bfa, Opuscula inedita, hrsg. \plain \f3\fs20 Andrzej Por\u279 \'ebbski, Warszawa 1978, S. 114-119, zu dieser Hs.}

