\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit soliloquium Gilberti ad gloriosissimam Virginem Mariam\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f1\i\lang1033\fs24\cf1 Mentem et oculos pariter cum manibus ad te, regina mundi, attollimus ... \plain \f1\lang1033\fs24\cf1 \endash   ... \plain \f1\i\lang1033\fs24\cf1 prestet hoc nobis, o Maria, tuo interuentu fructus Ihesus Deus et Dominus noster, cui est laus\plain \f1\lang1033\fs24\cf1  ... \plain \f1\i\lang1033\fs24\cf1 Amen\plain \f1\lang1033\fs24\cf1 .
