\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 76r-79r  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Notae et excerpta}}\plain \f1\b\lang1033\fs24\cf1   ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 David de Augusta}}\plain \f1\lang1033\fs24\cf1 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Bonaventura}}\plain \f1\b\lang1033\fs24\cf1  et al\plain \f1\lang1033\fs24\cf1 .)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 (76r)  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ex tractatu de profectibus religiosorum de caritate que sic diffinitur\plain \f1\lang1033\fs24\cf1 \u8249 \'8b\plain \f1\i\super\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1  Caritas est ordinata et magna voluntas\plain \f1\lang1033\fs24\cf1  ... \endash  (76r)  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Nota quod caritas est omnis virtus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Licet multe virtutes uideantur\plain \f1\lang1033\fs24\cf1  ... \endash  (76v) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Nota de humilitate triplici habenda scilicet ad nos, ad Deum, ad proximum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In nobis humiles esse debemus\plain \f1\lang1033\fs24\cf1  ... \endash   ... (78r)  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De obedientia que nascitur ex caritate, humilitate et patiencia\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Obediencia est proprie uoluntatis subiectio\plain \f1\lang1033\fs24\cf1  ... (78r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De humili obediencia ex tractatu Bonauenture cardinalis et doctoris eximii\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Quoniam ad uitam salutis nichil est tucius \plain \f1\lang1033\fs24\cf1 ...   \endash   78v leer. \endash   (79r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ex summa viciorum adde ad detestacionem murmurum\plain \f1\lang1033\fs24\cf1  \u8249 \'8b\plain \f1\i\lang1033\fs24\cf1  Legitur enim quod soror Moysi \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 qui accipit murmurare potest\plain \f1\lang1033\fs24\cf1 . \endash   79v-81v leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: David de Augusta, De exterioris et interioris hominis compositione secundum triplicem statum incipientium, proficientium et perfectorum libri tres, Quaracchi 1899;  Bonaventura, Regula novitiorum, Doctoris seraphici S. Bonaventurae opera omnia, Quaracchi 1898, 8, 488. \endash    Krijn Pansters, Franciscan Virtue: Spiritual Growth and the Virtues in Franciscan Literature and Instruction of the Thirteenth Century, Leiden, 2012. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 HS: Foliierungsvermerk.}

