\par \pard\sl254\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Expositio zum Prolog: \plain \f1\i\lang1033\fs24 Jhesu Christe \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Quamquam omnis sapiencia doctrina est et scientia\plain \f1\lang1033\fs24  \u8230 \'85  \plain \f1\i\lang1033\fs24 explicit exposicio regule \u8230 \'85, \plain \f1\lang1033\fs24 55vb Expositio zum Text:\plain \f1\i\lang1033\fs24  Incipit regula sancti patris nostri Benedicti \u8230 \'85 Monachorum quatuor esse genera \u8230 \'85 Expedito prologo nostre regule professionis \u8230 \'85 -\u8230 \'85 Explicit expositio regule.
