\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\i\lang1033\fs24 Capitula super regulam beati Benedicti. Audi fili patrem de somno modo surge\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia Carminum 1697. Melk, Beneditinerstift, Cod. 1405,1ra. \endash  \plain \f1\i\lang1033\fs24 Gradus discipline regularis. Admonet, increpat, excommunicat\plain \f1\lang1033\fs24  \u8230 \'85 Vgl. Melk, Benediktinerstift Cod. 1558,203v.}

