\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In nomine Domini\plain \f1\lang1033\fs24\cf1  ...\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Sacrosancte generali sinodo Basiliensi\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 Johannes patriarcha Anthiohenus\plain \f1\lang1033\fs24\cf1  \u8230 \'85  \endash   \plain \f1\i\lang1033\fs24\cf1 Quia nonnulli os suum aperientes in celum\plain \f1\lang1033\fs24\cf1  \u8230 \'85  \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 et alia supradicta obedire tenetur etc\plain \f1\lang1033\fs24\cf1 .  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Et sic est finis huius opusculi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  19v-21v leer.
