\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 \u220 \'dcberschrift: \plain \f1\i\lang1033\fs24\cf1 In Christi nomine Amen. 1458\plain \f1\lang1033\fs24\cf1 . Hand Schwerzenbecks: \plain \f1\i\lang1033\fs24\cf1 Epistola patris Johannis Schlippacher\plain \f1\lang1033\fs24\cf1  \plain \f2\lang1033\fs24 \endash \plain \f2\i\lang1033\fs24  \plain \f1\i\lang1033\fs24\cf1 Patri sincerius sibi precolendo patri videlicet Bernhardo Tegernseensis cenobii digno priori\plain \f1\lang1033\fs24\cf1  ... \plain \f2\lang1033\fs24 \endash  ...\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 te ipsum habere ostendisti evidenter. Explicit die sancti Augustini\plain \f1\lang1033\fs24\cf1  [1458 Aug. 28].
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
