\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 358ra-365ra  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Laudivius Hierosolymitanus}}\plain \f1\lang1033\fs24\cf1 :\~{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Vita Hieronymi}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 (358ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Laudiuius eques Jerosolimitanus ad Francinum Beltrandum Barchinonensem de vita beati Jeronimi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\lang1033\fs20\cf1 \endash  \plain \f1\lang1033\fs24\cf1 Prolog: \plain \f1\i\lang1033\fs24\cf1 Cum tuo sepe hortatu, Francine\plain \f1\lang1033\fs24\cf1  ...  \endash  (358vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit prologus. Capitulum primum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  Text: \plain \f1\i\lang1033\fs24\cf1 Ieronimi pater fuit Eusebius\plain \f1\lang1033\fs24\cf1  ... \endash  ... (365ra) \plain \f1\i\lang1033\fs24\cf1 ac meliora deinceps afferamus\plain \f1\lang1033\fs24\cf1 . \plain \f1\i\lang1033\fs24\cf1 Deo gracias finis huius operis\plain \f1\lang1033\fs24\cf1 .  \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ecce finis. Laus Deo, pax viuis et requies eterna defunctis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Finis vite Jeromymi per Laudiuium equitem Jerosolimitanum edite anno domini 1473 die quarta decima junij in alma vrbe Neapoli\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Culmine qui resides sublimi doctor olimpi, erige nunc proprios Jeronyme noster alumnos\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  365rb-369v leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 Druck: GW M17204, M17206-M17208. \endash  Lit.: Eugene F. \plain \f1\scaps\lang1033\fs20 Rice\plain \f1\lang1033\fs20 , Saint Jerome in the Renaissance (Baltimore: Johns Hopkins University Press, 1985), S. 102-104.}

