\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Da man zalt von Christi gepurde vii \plain \f1\lang1033\fs24 [hundert] \plain \f1\i\lang1033\fs24 iar vnd in dem lxxvi iar da was ain babst \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 vnd g\u252 \'fcter vrbar vil \plain \f1\lang1033\fs24 // Textabbruch. \endash  85v, 87r-v leer.
