\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 11va-16va {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Thomas de Aquino}}\plain \f1\b\lang1033\fs24 : Expositio in orationem dominicam
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Ihesus. Explanacio super oracione dominica scilicet Pater noster\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Pater noster. Inter alias oraciones dominica oratio excellencior inuenitur. Habet enim 5 excellencias \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 et ad hoc remouendum petimus. Sed libera nos a malo. Amen. Fiat \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit\plain \f1\lang1033\fs24 \u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Edition: S. Thomae Aquinatis Opera omnia VI, hrsg. von Roberto Busa. Stuttgart/Bad Cannstatt 1980, S. 22-25.}

