\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Pater. Filius. Explanacio sancti Thome super symbolo apostolorum\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Credo in deum ... Primum quidem necessarium est cuilibet Christiano esse in fide \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 venturus est ad iudicium. Rogemus ergo etc. Amen. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit\plain \f1\lang1033\fs24 \u8249 \'8b
