\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 110r-158r \plain \f1\b\lang1033\fs24 Sermones in concilio Basiliensi habiti
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (110r) \plain \f1\i\lang1033\fs24 Sermo magistri prioris sancti Benigni ordinis sancti Benedicti \plain \f1\lang1033\fs24 [Divionensis, Dijon] \plain \f1\i\lang1033\fs24 factus Basilee in dominica \plain \f1\lang1033\fs24 [\plain \f1\i\lang1033\fs24 Letare\plain \f1\lang1033\fs24 , von sp\u228 \'e4terer Hand korr. aus \plain \f1\i\lang1033\fs24 lx\plain \f1\i\super\lang1033\fs24 me\plain \f1\lang1033\fs24 ]. \endash  \plain \f1\i\lang1033\fs24 Vt inter corporalia ieiunia mentes nostre uerbi dei pane quo interior homo nutritur \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (115v) Martinus Berruerii: \plain \f1\i\lang1033\fs24 Sermo magistri Martini decani Turonensis factus dominica in passione domini in concilio Basiliensi. \endash  Surge propera \plain \f1\lang1033\fs24 ... (Ct 2,10). \plain \f1\i\lang1033\fs24 Vox hec sponsi ad sponsam\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 utique ubi ad amicam Christi \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (120\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 In magna sexta feria in Basiliensi concilio factus sermo. \plain \f1\lang1033\fs24 \endash  \plain \f1\i\lang1033\fs24 Consummatum est \plain \f1\lang1033\fs24 ... (Io 19,30). \plain \f1\i\lang1033\fs24 Reverendissimi etc. Cum oratoris officium sit ad rem et ad personas ac cetera circumstancia dicere \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24 (152r) [Sermo] \plain \f1\i\lang1033\fs24 prioris sancti Benigni \plain \f1\lang1033\fs24 [nachgetragen: \plain \f1\i\lang1033\fs24 dominica 21 post pentecostes\plain \f1\lang1033\fs24 ]. \endash  \plain \f1\i\lang1033\fs24 Simile est regnum \plain \f1\lang1033\fs24 ... (Mt 13,24) ... \plain \f1\i\lang1033\fs24 Quia secundum Hylarium intelligencia dictorum ex causis est assumenda dicendi \plain \f1\lang1033\fs24 ... \endash  131r-v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Parallelhss.: 1, 2 und 10 = u.a. Klosterneuburg, Augustiner-Chorherrenstift, Cod. 516, 155r-162v (Sermo 1), 162v-170r (Sermo 2), 194v-200r (Sermo 7), 270r-279r (https://manuscripta.at/?ID=690). \endash  3 = u.a. Jena, Th\u252 \'fcringische UuLB, Ms. El. phil. q. 7, 314r-322r. }

