\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 158v-163v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Keck}}\plain \f1\b\lang1033\fs24 : Sermo de angelis (1441 September 9)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Sermo fratris Iohannis Kek de Tegernsee in theologia magistri ad sacrosanctam generalem Basiliensem synodum de Angelis. \endash  Angeli eorum in celis \plain \f1\lang1033\fs24 ... (Mt 18,10). \plain \f1\i\lang1033\fs24 Sacrosancta generalis synode Basiliensis ... videns ego me stantem in medio tui quasi ymmo vix infantis similitudinem gerentem \plain \f1\lang1033\fs24 ... \endash  164r-v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Autograph. \endash  Druck: VD16 K 584 (Klosterdruckerei Tegernsee 1574). Lit.: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 4 (1983), Sp. 1101 Nr. IX,45 (Heribert Rossmann, Hs. genannt).}

