\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 171r-171v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gerardus Landrianus}}\plain \f1\b\lang1033\fs24 : Oratio ad universitatem Coloniensem (1432)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Sequitur oraciuncula Gherardi Laudriani episcopi Laudensis oratoris sacri Basiliensis concilii ad plenam et notabilem vniuersitatem Coloniensem\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 anno M\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  cccc\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  xxxii \plain \f1\lang1033\fs24 [1432]. \plain \f1\i\lang1033\fs24 Operemur bonum \plain \f1\lang1033\fs24 ... (Gal 6,10) ... \plain \f1\i\lang1033\fs24 Non eo nunc animo hec a nobis nomine sacri concilii Basiliensis sanctissimo vestro ordini proposita sunt \plain \f1\lang1033\fs24 ... 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Parallelhs.: Melk, Benediktinerstift, Cod. 940 (215, E 5), 120v-121v (https://manuscripta.at/?ID=36616). }

