\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 88r-92v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Johannes de Aragonia}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Tractatus brevis de articulis fidei, sacramentis ecclesiae, praeceptis decalogi, virtutibus et viciis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tractatus breuis \plain \f1\lang1033\fs24\cf1 (von Schwerzenbeck erg\u228 \'e4nzt: \plain \f1\i\lang1033\fs24\cf1 vtilis pro curatis animarum\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 de articulis fidei sacramentis ecclesie preceptis decalogi virtutibus et viciis compilatus ex doctoris sentenciis\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Beatus petrus apostolus qui promissionem accepit \plain \f1\lang1033\fs24\cf1 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 Ad quam gloriam post huius vite exilium dominus noster Ihesus Christus sue sacratissime passionis meritis nos perducat \plain \f1\lang1033\fs24\cf1 \u8230 \'85\plain \f1\i\lang1033\fs24\cf1  Amen\plain \f1\lang1033\fs24\cf1 . \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ihesus Maria\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  (88v) Am unteren Blattrand Vers: \plain \f1\i\lang1033\fs24\cf1 barba carens pilis est omni tempore vilis \plain \f1\lang1033\fs24\cf1 (Memorialvers zu den Sakramenten). \endash  93r-v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Parallelhss.: Graz, UB, Ms 655, 152v (https://manuscripta.at/?ID=5008). \endash  Teil\u252 \'fcberlieferung in Mainz, StB, Hs I 471a, 75r-81v. \endash  Bloomfield Nr. 624.}

