\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 239vb-241ra {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Eusebius Conradus}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Disputatio de s. Augustino}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (239vb) \u8250 \'9b\plain \f1\i\lang1033\fs24 Disputacio canonicorum regularium et Augustinensium mendicancium siue heremitarum et primo opinio monachorum scribencium ad canonicos regulares\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\i\lang1033\fs24  Patres et domini reuerendi vos fecistis nobis instanciam ... \endash  ... et non fiat inter nos altercacio. \endash  \plain \f1\lang1033\fs24 (239ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 Responsio canonicorum regularium\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Fratres et patres karissimi pensantes amoris affectum quem ad uos semper hactenus habuimus \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 et multorum doctorum veridica testimonia contestantur etc. }

