\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (317ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo de sancto Benedicto abbate\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ecce nos reliquimus \plain \f1\lang1033\fs24 \u8230 \'85 (Mt 19,27). \plain \f1\i\lang1033\fs24 Sancti patris nostri Benedicti solemnia que solis nobis anima reduxit canticis et ymnis \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (317va) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo de sancto Benedicto abbate\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Quicumque honorificabit me \plain \f1\lang1033\fs24 \u8230 \'85 (I Sm 2,13). \plain \f1\i\lang1033\fs24 Dicit Gregorius: ille deum veraciter honorat qui interiorem suum hominem \plain \f1\lang1033\fs24 \u8230 \'85
