\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (75ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Andrea apostolo\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Illi continuo relictis \plain \f1\lang1033\fs24 ... (Mt 4,22). \plain \f1\i\lang1033\fs24 Hoc verbum dicitur de sancto Andrea et Petro quos dominus vocauit ad gloriam apostolatus ...\plain \f1\lang1033\fs24  \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (75vb) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Andrea sermo 2us\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Michi absit gloriari \plain \f1\lang1033\fs24 ... (Gal 6,14). \plain \f1\i\lang1033\fs24 Hoc uerbum potest praedicari ad laudem sancti Andree apostoli qui prae omnibus sanctis \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (77ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Andrea sermo tercius\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ascendam in palmam \plain \f1\lang1033\fs24 ... (Ct 7,8). \plain \f1\i\lang1033\fs24 Hoc verbum potest praedicari de beato Andrea apostolo in quo describitur mortis eius qualitas \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\super\lang1033\fs24 148\plain \f1\lang1033\fs24 (203ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo ad nouos sacerdotes\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Vos elegit deus \plain \f1\lang1033\fs24 ... (II Par 29,11). \plain \f1\i\lang1033\fs24 Et sunt ista uerba dicta ad Levitas qui fuerunt clerici \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 149\plain \f1\lang1033\fs24 (204vb) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo secundus ad sacerdotes\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Bonitatem et disciplinam \plain \f1\lang1033\fs24 ... (Ps 118,66). \plain \f1\i\lang1033\fs24 In uerbis istis tria tanguntur scilicet caritatis dignitas \plain \f1\lang1033\fs24 ... \endash  (206ra-208vb) Index sermonum.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 1 = Schneyer, RLS 3, S. 171 Nr. 79. \endash  2 = ebd. S. 172 Nr. 80. \endash  3 = Schneyer, RLS 7, S. 291 Nr. 3. \endash  148 = ebd., S. 301 Nr.150. \endash  149 = ebd., Nr. 151. }

