\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 2ra-77rb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24\cf1 :{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1  Sermones dominicales de tempore (pars aestivalis)}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Sermones magistri Nycolai de Dinckel\plain \f1\lang1033\fs24\cf1 [spuhel] \plain \f1\i\lang1033\fs24\cf1 de caritate et eius effectibus \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (2ra) \plain \f1\i\lang1033\fs24\cf1 Si quis diligit \plain \f1\lang1033\fs24\cf1 ... (Io 14,23). \plain \f1\i\lang1033\fs24\cf1 Sicut tradunt doctores circa distinctionem primam primi sententiarum nullus actus noster bonus est \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (6va) \plain \f1\i\lang1033\fs24\cf1 Posset aliquis querere cum deus sit ubique et impossibile sit \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (11rb) \plain \f1\i\lang1033\fs24\cf1 Preter signa de quibus in praecedenti sermone dictum est \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\super\lang1033\fs24\cf1 28\plain \f1\lang1033\fs24\cf1 (71va) \plain \f1\i\lang1033\fs24\cf1 Simile factum est \plain \f1\lang1033\fs24\cf1 ... (Mt 18,23). \plain \f1\i\lang1033\fs24\cf1 Secundum Remigium regnum celorum est ecclesia militans \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 29\plain \f1\lang1033\fs24\cf1 (73vb) \plain \f1\i\lang1033\fs24\cf1 Sicut ante hoc ewangelium ponit dominus phariseis et senioribus populi \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 30\plain \f1\lang1033\fs24\cf1 (75rb) \plain \f1\i\lang1033\fs24\cf1 Princeps vnus archisynagogus \plain \f1\lang1033\fs24\cf1 ... (Mt 9,18). \plain \f1\i\lang1033\fs24\cf1 Ex hoc sermone Crysostomi hostes Christi non solum ex verbis eius \plain \f1\lang1033\fs24\cf1 ... \endash  77v-84v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Madre, S. 146 Nr. 50-52, 76-78. Sermo 3 = Madre, S. 213 (Pfingstpredigt). }

