\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 V (217-276)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 217ra-271va {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermones de sanctis}}\plain \f1\b\lang1033\fs24\cf1  
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermones magistri Nicolai de sanctis tempore estiuali\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (216ra) Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Sermo de sancto Iohanne waptista \plain \f1\lang1033\fs24\cf1 (!)\plain \f1\i\lang1033\fs24\cf1 . \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 Quis putas puer \plain \f1\lang1033\fs24\cf1 ... (Lc 1,66). \plain \f1\i\lang1033\fs24\cf1 Cum parentes et cognati ac vicini beati Iohannis waptiste \plain \f1\lang1033\fs24\cf1 (!)\plain \f1\i\lang1033\fs24\cf1  vidissent \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (221rb) \plain \f1\i\lang1033\fs24\cf1 Rogabat Ihesum quidam phariseus \plain \f1\lang1033\fs24\cf1 ... (Lc 7,36). \plain \f1\i\lang1033\fs24\cf1 Conuersio et poenitencia beate Marie Magdalene data est nobis in exemplum \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (228ra) \plain \f1\i\lang1033\fs24\cf1 Postquam cepi vobis loqui de diuinis praeceptis interuenit festum beati Iacobi apostoli \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 8\plain \f1\lang1033\fs24\cf1 (250rb) \plain \f1\i\lang1033\fs24\cf1 Maria optimam partem \plain \f1\lang1033\fs24\cf1 ... (Lc 10,42). \plain \f1\i\lang1033\fs24\cf1 Omnipotens dominus in multis excellenciis et praerogatiuis virginem Mariam\plain \f1\lang1033\fs24\cf1  ... \endash  \plain \f1\super\lang1033\fs24\cf1 9\plain \f1\lang1033\fs24\cf1 (257rb) \plain \f1\i\lang1033\fs24\cf1 Angeli eorum in caelis \plain \f1\lang1033\fs24\cf1 ... (Mt 18,10). \plain \f1\i\lang1033\fs24\cf1 Et legitur in hodierno ewangelio. Quamuis non videamus apparicionem angelorum \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 10\plain \f1\lang1033\fs24\cf1 (263va) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo alius de eodem\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In illa hora accesserunt \plain \f1\lang1033\fs24\cf1 ... (Mt 18,1). \plain \f1\i\lang1033\fs24\cf1 Hoc ewangelium habet tres partes in quarum prima dominus loquitur de humilitate \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 de festiuitate angelorum etc. Finis anno m\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\lang1033\fs24\cf1  [cccc\plain \f1\super\lang1033\fs24\cf1 o\plain \f1\lang1033\fs24\cf1 ]\plain \f1\i\lang1033\fs24\cf1  lx\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 [1460]. \endash  272r-276v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 In dieser Reihenfolge: Madre, S. 238 Nr. III, 240 Nr. 4, 242 Nr. V, 227 Nr. 4, 1235 Nr. II,1 und 237 Nr. II,2.}

