\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 2ra-233vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Matthaeus de Saxonia}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Postillae super evangelia per quadragesimam}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipiunt postille super ewangelia per quadragesimam per fratrem Matheum de Saxonia \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b (2ra) \plain \f1\i\lang1033\fs24\cf1 In illo tempore dixit Ihesus \plain \f1\lang1033\fs24\cf1 ... (Mt 6,16). \plain \f1\i\lang1033\fs24\cf1 Ecce fratres dilectissimi in Domino nunc est tempus acceptabile \plain \f1\lang1033\fs24\cf1 ... \endash  (5va) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Feria quinta post diem cinerum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In illo tempore cum intrasset \plain \f1\lang1033\fs24\cf1 ... (Mt 8,5). \plain \f1\i\lang1033\fs24\cf1 In ewangelio hesterno saluator docuit nos modum ieiunandi \plain \f1\lang1033\fs24\cf1 ... \endash  (7vb) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Feria 25\plain \f1\i\super\lang1033\fs24\cf1 a\plain \f1\i\lang1033\fs24\cf1  post diem cinerum. Secundum Matheum\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In illo tempore dixit Ihesus discipulis \plain \f1\lang1033\fs24\cf1 ... (Mt 5,21). \plain \f1\i\lang1033\fs24\cf1 In ewangelio hesterno saluator docuit nos virtutem fidei \plain \f1\lang1033\fs24\cf1 ... \endash  ... (227ra) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Feria vi\plain \f1\i\super\lang1033\fs24\cf1 a\plain \f1\i\lang1033\fs24\cf1  pasche secundum Iohannem\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In illo tempore vndecim discipuli \plain \f1\lang1033\fs24\cf1 ... (Mt 28,16). \plain \f1\i\lang1033\fs24\cf1 Habitis apparicionibus precedentibus et de diversis effectibus \plain \f1\lang1033\fs24\cf1 ... \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Expliciunt postille super ewangelia per xlam fratris Mathei de Saxonia ordinis heremitarum anno 73\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  (231rb-233vb) Sachregister: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tabula huius hic habetur\plain \f1\lang1033\fs24\cf1 \u8249 \'8b ... \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit tabula postillarum super ewangelia fratris Mathei de Saxonia anno 73\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  per quadragesimam\plain \f1\lang1033\fs24\cf1 \u8249 \'8b Darunter von anderer Hand: \plain \f1\i\lang1033\fs24\cf1 1474\plain \f1\lang1033\fs24\cf1 .
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Zumkeller, Manuskripte Nr. 681 S. 328-329, Hs. genannt, mit weiterer \u220 \'dcberlieferung.}

