\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24 Lectiones per aliquas sententias de beata virgine Maria ex reuelacionibus sancte Brigitte vidue de Suecia. \plain \f1\lang1033\fs24 \endash  // \plain \f1\i\lang1033\fs24 esset conueniens et dignum quod dies illa...\plain \f1\lang1033\fs24  \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 feria quarta leccio secunda absolucio\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Stella Maria maris succurrat piissima nobis. Deinde postquam illa benedicta materia congrue \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 tempore fortueum corpus \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 in sui benedicti filii regnum eternum.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Sancta Birgitta, Opera minora 2: Sermo angelicus, hrsg. von S. Eklund. Uppsala 1972, hier lib. XI, c. 11-15.}

