\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Secuntur loca siue ecclesie stacionum magnarum indulgenciarum sacre urbris \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 Rome per totam quadragesimam\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Feria quarta cinerum statio ad sanctam Sabinam \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 et contritus de peccatis suis. Amen. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Expliciunt indulgencie curie Romane in profesto sancti Lamperti episcopi anno domini m\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1 cccc\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1 lxviii \plain \f1\lang1033\fs24\cf1 [korr. aus \plain \f1\i\lang1033\fs24\cf1 lxviiii\plain \f1\lang1033\fs24\cf1 ]\u8249 \'8b [1468 September 17]. \endash  311v-317v leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Lit.: Alois Wei\u223 \'dfthanner, Mittelalterliche Rompilgerf\u252 \'fchrer, in: Archivalische Zeitschrift 49 (1954), S. 39-64, Hs. genannt S. 43. }

