\pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24 181rb-220ra {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones}}
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (181ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo in annunciacione beate Marie virginis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ingressus clausit hostium \plain \f1\lang1033\fs24 ... (II Rg 4,33). \plain \f1\i\lang1033\fs24  Conscriptissimi patres et domini prestantissimi ingredientem indebite clausa dominice incarnacionis \u8230 \'85\plain \f1\lang1033\fs24  \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (185va) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo in festiuitate omnium sanctorum\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Ipsorum est regnum \plain \f1\lang1033\fs24 (Mt 5,3). \plain \f1\i\lang1033\fs24 Sic scribitur Matthaeus v originaliter et in presentis sanctissime festiuitatis ewangelio transsumptiue habetur \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (191va) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo in die concepcionis virginis gloriose\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Liber \plain \f1\lang1033\fs24 [generationis] \plain \f1\i\lang1033\fs24 et subauditur\plain \f1\lang1033\fs24  ... (Mt 1,1).\plain \f1\i\lang1033\fs24  Sic scribitur Matthaeus 1 originaliter et in praesentis sacratissime festiuitatis ewangelio transsumptiue habetur et hystorialiter \plain \f1\lang1033\fs24 \u8230 \'85 \endash  ... \plain \f1\super\lang1033\fs24 15\plain \f1\lang1033\fs24 (226va) \u8250 \'9b\plain \f1\i\lang1033\fs24 Sermo de omnibus sanctis\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Exultabunt sancti \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (Ps 149,5). \plain \f1\i\lang1033\fs24 Verba praeassumpta scribuntur libro psalmorum psalmo penultima que quidem verba pro presentis festiuitatis omnium sanctorum recommendacione \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \plain \f1\super\lang1033\fs24 16\plain \f1\lang1033\fs24 (230ra) \u8250 \'9b\plain \f1\i\lang1033\fs24 De sancto Dominico\plain \f1\lang1033\fs24 \u8249 \'8b\plain \f1\scaps\lang1033\fs24  \plain \f1\i\lang1033\fs24 Magnus vocabitur in regno \plain \f1\lang1033\fs24 ... (Mt 5,19). \plain \f1\i\lang1033\fs24 Verba proposita Mt v\plain \f1\i\super\lang1033\fs24 to\plain \f1\i\lang1033\fs24  originaliter sunt scripta et in inchoantis sacratissime festiuitatis ewangelio sunt legenda \plain \f1\lang1033\fs24 \u8230 \'85 \endash  (182r) oben von anderer Hand Versus: \plain \f1\i\lang1033\fs24 Littera gesta docet quid credas allegoria  \plain \f1\lang1033\fs24 ... (Walther, Initia Nr. 13899). \endash  232v-VII\rquote v leer.
\par \pard\fi0\li0\tx4605\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20 1 = Stegm\u252 \'fcller\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20 RB 1183. \endash  2 = Stegm\u252 \'fcller, RB 1184.}

