\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Doctrina eiusdem pro deuotis simplicibus \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 originaliter edita in vvlgari gallico in latinum per alium translata\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Deus vvult ut sit rationabile obsequium nostrum ita ut cuncta quae in eius seruicio facimus \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 sibi laus gloria et gratiarum accio semper. Amen. Laus deo. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ecce finem\plain \f1\lang1033\fs24\cf1 \u8249 \'8b
