\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 115v-120vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Iohannes Gerson}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 De auferibilitate sponsi ab ecclesia}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tractatus magistri Iohannis Gerson de aufferabilitate \plain \f1\lang1033\fs24\cf1 (!)\plain \f1\i\lang1033\fs24\cf1  sponsi et pape ab ecclesia\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Venient autem dies \plain \f1\lang1033\fs24\cf1 ... (Mt 9,15). \plain \f1\i\lang1033\fs24\cf1 Circa quem textum prima nunc currente quaeritur si aufferibilis sit \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 et nostrum omnium salutem praestante eodem \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Amen. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit tractatus magistri Iohannis Gerson de aufferibilitate \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Gerson, \u338 \'8cuvres compl\u232 \'e8tes 3, S. 294-313.}

