\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 121ra-123ra {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Iohannes Gerson}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 De auctoritate concilii universalem ecclesiam repraesentantis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Tractatus eiusdem magistri Iohannis Gerson de congregacione generali ecclesie sine auctoritate pape \plain \f1\lang1033\fs24\cf1 ...\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In sequenti opere ad videndum de auctoritate congregacionis fidelium vniversalem ecclesiam repraesentantis \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 quia iam durabit \plain \f1\lang1033\fs24\cf1 (! vielm. duravit) \plain \f1\i\lang1033\fs24\cf1 praesens scisma per xxxi annos. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Deo gratias 1454. Explicit tractatus\plain \f1\lang1033\fs24\cf1  ...\u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Gerson, \u338 \'8cuvres compl\u232 \'e8tes 6, S. 114-123 Nr. 269.}

