\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 123rb-125ra {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Iohannes Gerson (?)}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermo de morbis ecclesiae}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit tractatus magistri Iohannis Gerson de tribulacionibus ex defectuoso ecclesiasticorum regimine \plain \f1\lang1033\fs24\cf1 ... [Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Sermo est quod fecit de conceptione beate virginis in concilio Constantiensi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Dominus dabit uobis signum \plain \f1\lang1033\fs24\cf1 ... (Is 7,14). \plain \f1\i\lang1033\fs24\cf1 Nunc ad 2\plain \f1\i\super\lang1033\fs24\cf1 m\plain \f1\i\lang1033\fs24\cf1 . Reverendissimi patres et domini\plain \f1\lang1033\fs24\cf1  \plain \f1\i\lang1033\fs24\cf1 restat ostendere quomodo signum \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 propter hoc dabit dominus ipse uobis signum. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit 1454\plain \f1\lang1033\fs24\cf1 \u8249 \'8b
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Du Pin II, 1706, Sp. 309-313. \endash  Lit.: Glorieux, Jean Gerson, Oeuvres compl\u232 \'e8tes 5, 1963, p. XVII rechnet dieses Werk zu den unechten Schriften. }

