\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 294rb-296rb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Iohannes Stedler de Landshut}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermo in concilio Basiliensi factus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Sermo magistri Iohannis St\u228 \'e4edler doctoris factus in synodo ad congregatos. \endash  Sacerdotes contempserunt legem \plain \f1\lang1033\fs24\cf1 ... (Ez 22,26). \plain \f1\i\lang1033\fs24\cf1 Quia reverende mihi reverendissime pontifex \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 auctor inuidie serpens ille antiquus non sinens hominem illuc ascendere \plain \f1\lang1033\fs24\cf1 ... \endash  296v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Datierung laut Inhaltsverzeichnis (Ir): \plain \f1\i\lang1033\fs20\cf1 Sermo domini Iohannis St\u228 \'e4dler canonici et vicarii in spiritualibus Frisingensis diocesis doctoris egregii factus in synodo Basiliensi coram congregatione die martis post dominicam Misericordia domini anno 1456 \plain \f1\lang1033\fs20\cf1 (! vielleicht 1436 gemeint?)\plain \f1\i\lang1033\fs20\cf1 .}

