\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 Ir-v leer. \endash  IIr: Stiftungsvermerk von Schwerzenbeck: \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 1482\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Istum librum obtulit deo et sancto Quirino in Tegernsee venerabilis dominus Iohannes Teybler olim plebanus in Egern. \plain \f1\lang1033\fs24\cf1 \endash  Darunter Inhaltsverzeichnis. \endash  IIv leer.
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 1ra-4vb {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iohannes de Frankfordia}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de contractibus}}
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit tractatus de contractibus compositus per magistrum Iohannem de Franckfurdia doctorem in theoloya \plain \f1\lang1033\fs24 (!)\u8249 \'8b \plain \f1\i\lang1033\fs24 Ut in foro anime vbi inspector sit deus salubrius valeas consulere \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 et tributarias vrgente penuria eas compellente etc\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Et sic est finis huius tractatus de contractibus ... \plain \f1\lang1033\fs24 (wie oben) \plain \f1\i\lang1033\fs24 scriptus per Iohannem R\u228 \'e4m rectorem in H\u228 \'e4bach anno domini m cccc lviii \plain \f1\lang1033\fs24 [1458] \plain \f1\i\lang1033\fs24 4ta feria in medio ieiunii. 
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs20 Parallel\u252 \'fcberl. u.a.: Clm 11468, 35ra-41va. \endash  Eichst\u228 \'e4tt, UB, Cod. st 465, 337ra-341vb. \endash  Lit.: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 4 (1983), Sp. 599-603, insb. Sp. 601 Nr. 3 (Rudolf Haubst, Hs. genannt). \endash  Johann Friedrich Freiherr von Schulte, Die Geschichte der Quellen und Literatur des kanonischen Rechts 2. Stuttgart 1877, S. 437. }

