\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 II (188-190)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 188r-190v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Keck}}\plain \f1\b\lang1033\fs24 : Sermo in concilio Basiliensi habitus [1442]
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Sermo de benedicta trinitate \plain \f1\lang1033\fs24 [Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24 magistri Iohannis Keck doctoris nostri in Tegernsee habitus in concilio Basiliensi coram papa Felice 5\plain \f1\i\super\lang1033\fs24 to\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 . \plain \f1\lang1033\fs24 \endash  \plain \f1\i\lang1033\fs24 Tres vnum etc. \plain \f1\lang1033\fs24 (Io 5,8). \plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Sanctissime pater cardinales mundi dignissimi archipresules presulesque ... locutor michi de summa ac indiuidua trinitate \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 claram stabilem sine fine gerere mereamur \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. Pronunciatus est hic sermo per me Io\plain \f1\lang1033\fs24 [hannem]\plain \f1\i\lang1033\fs24  Keck in sacro Basiliensi concilio coram sanctissimo domino nostro domino Felice diuina prouidentia papa quinto in festo sancte trinitatis anno domini 1442 \plain \f1\lang1033\fs24 [1442].\plain \f1\i\lang1033\fs24   
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Autograph. \endash  Druck: VD16 K 584 (Tegernsee 1574). \endash  Lit.: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 4 (1983), Sp. 1100 Nr. VIII,50 (Heribert Rossmann, Hs. genannt). }

