\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Nota casus papales\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Primo falisificatores litterarum papalium tam principales quam fautores \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 temere peccancium introductam. Sit laus honor et gloria Christo. Amen. \plain \f1\lang1033\fs24 \endash  194v-195v leer.
