\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 [\u220 \'dcbergeschrieben: \plain \f1\i\lang1033\fs24 Heinrici de frimaria\plain \f1\lang1033\fs24 ] \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit tractatus de septem viciis qualiter se occultant sew palliant sub specibus virtutum ne cognoscantur ab homine\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Est via que videtur \plain \f1\lang1033\fs24 \u8230 \'85 (Prov 14,12). \plain \f1\i\lang1033\fs24 Quia 2\plain \f1\i\super\lang1033\fs24 um \plain \f1\i\lang1033\fs24 gregorium 92 moralium multa sunt vicia que sub specie virtutum se occultant \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 hospicis poterimus extropare quod nobis praestare dignetur \plain \f1\lang1033\fs24 \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen. \plain \f1\lang1033\fs24 \endash  278r-v leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Lit.: Zumkeller, Manuskripte Nr. 316. }

