\pard\fi0\li0\qc\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 IV (279-281)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 279r/288r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Tudeschis}}\plain \f1\b\lang1033\fs24 : Epistola (Basel, 1443 Januar 16)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Ex responsione hiis diebus per quondam Eugenum papam quintum \plain \f1\lang1033\fs24 (! vielm. \plain \f1\i\lang1033\fs24 quartum\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  de serenissimi regis Romanorum \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 (nach 279v Fortsetzung des Briefes auf 288r): \plain \f1\i\lang1033\fs24 \u8230 \'85 qui non obedierit ecclesie sit tibi sicut ethnicus et publicanus etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Folgerungen des Erzbischofs Nicolaus von Palermo aus der Antwort Eugens IV. an die k\u246 \'f6nigliche Gesandtschaft zum Basler Konzil. \endash  Edition: RTA 17 (1442-1445), Nr. 42, S. 86-89 mit weiterer \u220 \'dcberlieferung.}

