\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 282r-285v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Keck}}\plain \f1\b\lang1033\fs24 : Sermo in concilio Basiliensi  (1441 Dezember 3)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24 Sermo egregius factus in Concilio Basiliensi dominica prima in aduentu domini. Erunt signa. \endash  Erunt signa \plain \f1\lang1033\fs24 \u8230 \'85 (Lc 21,25). \plain \f1\i\lang1033\fs24 Habet ut ex sacris scripturis colligo pater beatissime ...  Clementissimus deus noster sol ipse supernus duo in se ipso signa \plain \f1\lang1033\fs24 \u8230 \'85 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Autograph. \endash  Druck: VD16 K 584 (Tegernsee 1574). \endash  Lit.: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 4 (1983), Sp. 1100 Nr. VIII,46 (Heribert Rossmann, Hs. genannt). }

