\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 287r \plain \f1\b\lang1033\fs24 Epistola universitatis Parisiensis ad Dionysium de Sabrevay et Nicolaum Amici (1443 Januar 22)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24 Venerabilibus et circumspectis viris dominis et magistris Dyonisio de Sabranais et Nicolao in sacro Basiliensi concilio oratoribus nostris carissimis etc \plain \f1\lang1033\fs24 [am Rand von Schwerzenbeck erg\u228 \'e4nzt: \plain \f1\i\lang1033\fs24 Rector et vniuersitas studii Parisiensis ad concilium Basiliense\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 Plurima vobis gratia scribere conuenit oratores eggregii dum vestra et aliorum operum sacra generalis synodus pro pace componenda \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 apud sanctum Maturinum solemniter celebrata anno domini m\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  cccc\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  xliii\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  die vero xxii Ianuarii \plain \f1\lang1033\fs24 [1443 Januar 22]. \plain \f1\i\lang1033\fs24 Rector et vniuersitas studii Parisiensis. \plain \f1\lang1033\fs24 \endash  288r siehe oben zu 279r (Schluss des Briefs). \endash  288v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Parallelhss.: Basel, UB, E I 4\plain \f1\lang1033\fs24 , \plain \f1\lang1033\fs20 503r-v mit abweichender Datierung auf 1442 Januar 17. }

