\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 101rb-172va {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Guilelmus Alvernus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De rhetorica divina}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit rethorica diuinalis de oratione domini Wilhelmi episcopi Parysiensis doctoris eximii\plain \f1\lang1033\fs24 \u8249 \'8b [dar\u252 \'fcber Hinweis: \u8250 \'9b\plain \f1\i\lang1033\fs24 licet titulus solum ponat de oratione includitur tamen integer primalis processus et multum egregius\plain \f1\lang1033\fs24 \u8249 \'8b]. \plain \f1\i\lang1033\fs24 In sacris ac sanctissimis recitacionibus quae et quanta sit dignitas \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 sed eciam impetratur ab ipso et gratia cui est honor et imperium \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 Amen. Ecce finem.\plain \f1\lang1033\fs24  \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit rethorica diuina de oratione \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  Anno domini 1452\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  finitus est liber iste proxima die post festum sanctorum martyrum Nerei Achilaii et Pangracii \plain \f1\lang1033\fs24 [1452 Mai 13] \plain \f1\i\lang1033\fs24 per fratrem Leonhardum Eggrer professum in Tegrinsee. Sit laus deo\plain \f1\lang1033\fs24 \u8249 \'8b. \endash  172vb leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Druck: Guilelmi Alverni Opera omnia I. Paris 1674, S. 336-406. \endash  Glorieux, R\u233 \'e9pertoire 1, S. 317 Nr. 141s. \endash  CALMA IV, 5 (2014), S. 583, 4.}

