\pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 151ra-156ra {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iohannes Schlitpacher de Weilheim}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Summula psalmorum materialis}}
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24 Summula psalmorum collecta per magistrum et patrem Iohannem Schlippacher Mellicensis cenobii monachum professum. \plain \f1\lang1033\fs24 \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24 De psalmorum materia quantum ad sensum literalem doctores sancti et scolastici sepe variantur \plain \f1\lang1033\fs24 ...\u8249 \'8b \plain \f1\i\lang1033\fs24 Beatus vir \plain \f1\lang1033\fs24 ... (Ps 1,1). \plain \f1\i\lang1033\fs24 Primus psalmus inducit ad studium sacre scripture quae in psalterio \plain \f1\lang1033\fs24 ... \endash  ... (155vb) \plain \f1\i\lang1033\fs24 Laudate dominum \plain \f1\lang1033\fs24 ... (Ps 150,1). \plain \f1\i\lang1033\fs24 Psalmus ultimus est inuitacio ad dominicam laudem\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 humiliter et fidenter postuletur \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 Amen. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Summula psalmorum finitur materialis ffesto Nazarii \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 1460 \plain \f1\lang1033\fs24 [1460 Juni 12]. \plain \f1\i\lang1033\fs24 Explicit\plain \f1\lang1033\fs24 \u8249 \'8b
\par \pard\sl252\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs20 Parallelshs.: Melk, Benediktinerstift, Cod. 960 (1, A 1), p. 414-423. \endash  \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 VL 8 (1992), Sp. 735 Nr. V,1c (Franz Josef Worstbrock, Hs. genannt mit unvollst\u228 \'e4ndiger Signatur: \plain \f1\i\lang1033\fs20 Clm 18524\plain \f1\lang1033\fs20 ). }

