\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 133r-152v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Thomas a Kempis}}\plain \f1\b\lang1033\fs24 : De disciplina claustralium
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit tractatus fratris Thome Kempis professi in monte sancte Agnetis ordinis canonicorum regularium sub capitulo Windeshemensi de disciplina claustralium ...\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Apprehendite disciplinam \plain \f1\lang1033\fs24 ... (Ps 2,12). \plain \f1\i\lang1033\fs24 Disciplina claustralis si strenue seruetur ad magnam perfeccionem ducit \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 vbi Christus est in gloria patris per eterna secula regnans. Amen. Explicit tractatus de disciplina claustralium fratris Thome Rempis \plain \f1\lang1033\fs24 (!) \plain \f1\i\lang1033\fs24 ordinis canonicorum regularium.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Thomae Hemerken a Kempis Opera omnia, Bd. 2, hrsg. von Michael Joseph Pohl, Freiburg 1904, S. 265-319, Hs. genannt S. 487 (Sigle T).}

