\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f2\super\lang1033\fs24\cf1 1\plain \f2\lang1033\fs24\cf1 (10v) \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Sermo sancti Maximi episcopi de sancto Laurencio martire\plain \f2\lang1033\fs24\cf1 \u8249 \'8b (11r) \plain \f2\i\lang1033\fs24\cf1 Sanctum est fratres ac deo placitum vt natalem sancti Laurencii praecipua deuocione veneremur \plain \f2\lang1033\fs24\cf1 ... \endash  \plain \f2\super\lang1033\fs24\cf1 2\plain \f2\lang1033\fs24\cf1 (12r) \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Alius sermo\plain \f2\lang1033\fs24\cf1 \u8249 \'8b \plain \f2\i\lang1033\fs24\cf1 Sicut patrum nostrorum fratres karissimi non incerta relatione didicimus \plain \f2\lang1033\fs24\cf1 ... \endash  \plain \f2\super\lang1033\fs24\cf1 3\plain \f2\lang1033\fs24\cf1 (13v) \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Sermo sancti Augustini episcopi tercia feria Letanie\plain \f2\lang1033\fs24\cf1 \u8249 \'8b \plain \f2\i\lang1033\fs24\cf1 Quoniam ieiuniorum tempus est fratres karissimi \plain \f2\lang1033\fs24\cf1 ... \endash  ... \plain \f2\super\lang1033\fs24\cf1 15\plain \f2\lang1033\fs24\cf1 (44v) \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Sermo exhortatorius ad timorem dei et alias virtutes\plain \f2\lang1033\fs24\cf1 \u8249 \'8b \plain \f2\i\lang1033\fs24\cf1 Debitores sumus quippe fratres karissimi salutis eterne \plain \f2\lang1033\fs24\cf1 ... \endash  ... \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Explicit per me fratrem Oswaldum Nott de Tittmaning monachum et professum in Tegernsee\plain \f2\lang1033\fs24\cf1 \u8249 \'8b \endash  \plain \f2\super\lang1033\fs24\cf1 16\plain \f2\lang1033\fs24\cf1 (47r) \u8250 \'9b\plain \f2\i\lang1033\fs24\cf1 Sermo sancti Maximi episcopi de sancto Laurencio martire\plain \f2\lang1033\fs24\cf1 \u8249 \'8b \plain \f2\i\lang1033\fs24\cf1 Beatissimi Laurencii fratres karissimi annua semperque noua festiuitas \plain \f2\lang1033\fs24\cf1 ... \endash   42v, 48v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f2\lang1033\fs20\cf1 1 = Ps.-Maximus Taurinensis, Hom. 74, PL 57, 408. \endash  Ps.-Maximus Taurinensis, Hom. 75, PL 57, 410-412. \endash  3 = Ps.-Augustinus, Sermo 175, PL 39, 2079-2080. \endash  16 = Ps.-Maximus Taurinensis, Hom. 76, PL 57, 413-414.}

