\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 216r-267v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Pius II papa}}\plain \f1\b\lang1033\fs24\cf1 : Epistola ad Mahumetem (1461)
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Epistola Pii pape vtilissima et optima in qua compendiose et quasi diotetenus \plain \f1\lang1033\fs24\cf1 (! vielm. idiote\plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 tenus?) \plain \f1\i\lang1033\fs24\cf1 tota series christiane fidei comprehenditur et machometea lex et fatuitas confutatur\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Pius episcopus \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Scripturi ad te aliqua pro tua salute et gloria \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 in cinerem totus morieris. Christus regnabit in eternum cui est honor \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Amen. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Explicit epistola per me fratrem Oswaldum Nott de Tittmaning professum et monachum in Tegernsee anno 1469\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \endash  268r-269v leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Edition u.a.: Pius II. papa: Epistola ad Mahumetem. Einleitung, kritische Edition, \u220 \'dcbersetzung, hrsg. von Reinhold F. Glei/Markus K\u246 \'f6hler. Trier 2001 (Bochumer Altertumswissenschaftliches Colloquium 50), S. 130-327, diese Hs. Sigle M\plain \f1\sub\lang1033\fs20\cf1 4\plain \f1\lang1033\fs20\cf1 .}

