\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Incipit planctus ecclesie secundum statum modernorum filiorum ...\plain \f1\lang1033\fs24 \u8249 \'8b \plain \f1\i\lang1033\fs24 Rogo corde pertractetur hoc breue compendium \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 iniquum ne consilium nos possit arrestare. \plain \f1\lang1033\fs24 \u8250 \'9b\plain \f1\i\lang1033\fs24 Explicit tractatus de planctu ecclesie. Deo gracias\plain \f1\lang1033\fs24 \u8249 \'8b
