\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sequitur excerptum quoddam a quodam tractatulo qui intitulatur Stimulus amoris et incipitur sic: Currite gentes vndique etc. Auctorem ignoro, puto tamen Bernhardus\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Stabat iuxta crucem \plain \f1\lang1033\fs24\cf1 ... (Io 19,25). \plain \f1\i\lang1033\fs24\cf1 O domina mea vbi stabas? Numquid iuxta crucem? \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 et sine vulnere non recedam. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Stimulus amoris fr. Iacobi Mediolanensis. Quaracchi \plain \f1\super\lang1033\fs20\cf1 2\plain \f1\lang1033\fs20\cf1 1949 (Bibliotheca Franciscana Ascetica Medii Aevi), S. 77-81. \endash  Lit.: zur Verfasserfrage Distelbrink, Bonaventura, Nr. 217/218. \endash  \plain \f1\super\lang1033\fs20\cf1 2\plain \f1\lang1033\fs20\cf1 VL 9 (1995), Sp. 335-341 (Falk Eisermann).}

