\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 156r-164v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Iohannes Wischler de Spira}}\plain \f1\b\lang1033\fs24\cf1 : Quaestio
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 Hinweis: \plain \f1\i\lang1033\fs24\cf1 Sequens quaestio determinata est per fratrem Iohannem de Spira monachum ordinis sancti Benedicti professi \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 nouissime in monasterio Celle Marie \plain \f1\lang1033\fs24\cf1 [Mariazell] \plain \f1\i\lang1033\fs24\cf1 Patauiensis diocesis. \plain \f1\lang1033\fs24\cf1 \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Vtrum res suo vsu consumptibilis possit quantum ad eundem vsum in alium transferri absque suo dominio\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Interrogauit me aliquis quidam religiosus vir magne sciencie et eloquentie an monachus in aliquo casu posset habere verum proprium \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 et hoc est contra Biridanum \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 eciam si dicto modo intelligatur. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Johannes Wischler de Spira, Prior von Melk und ab 1441 professus in Mariazell, zugeschrieben. Zu diesem siehe \plain \f1\super\lang1033\fs20\cf1 2\plain \f1\lang1033\fs20\cf1 VL 4 (1983), Sp. 757-760 (Herbert Kraume).}

