\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 119v-132r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Johannes von Kastl}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 De fine religiosae perfectionis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Incipit tractatus Alberti Magni de adherendo deo nudatu intellectu et affectu \plain \f1\lang1033\fs24\cf1 ... \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Cogitanti michi aliquid vltimate in quantum possibile est \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 a qua nos custodiat Ihesus Christus. Amen. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Ffinit tractatulus magni Alberti\plain \f1\lang1033\fs24\cf1 \u8249 \'8b [darunter von anderer Hand: \plain \f1\i\lang1033\fs24\cf1 qui attitulatur patri Iohanni Castellensi in libro decretorum \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 sed abbas Spanheimensis in libro de ecclesiasticis scriptoribus asscribit Alberto Magno\plain \f1\lang1033\fs24\cf1 ].
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Hier Albertus Magnus, von der Nachtragshand und im Inhaltsverzeichnis von Schwerzenbeck Johannes von Kastl zugeschrieben. \endash  Sudbrack, Johannes von Kastl, Bd. 1, S. 25-42 und 49-58. \endash  \plain \f1\super\lang1033\fs20\cf1 2\plain \f1\lang1033\fs20\cf1 VL 4 (1981), Sp. 654 (Josef Sudbrack). }

