\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 56v-64v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Petrus Iohannes Olivi}}\plain \f1\b\lang1033\fs24\cf1 : De septem sentimentis Christi Iesu
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Sermo seu tractatus subtilis de passione domini. \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 Hoc enim sentite \plain \f1\lang1033\fs24\cf1 ... (Phil 2,5). \plain \f1\i\lang1033\fs24\cf1 Secundum sententiam sancti Dyonisii summus et supremus gradus eleuacionis mentis in deum \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 septem gradus in ecclesia extinxerunt etc. Amen. \plain \f1\lang1033\fs24\cf1 Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Explicit sermo seu tractatus de passione domini. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Edition: Marco Bartoli, Il \u8222 \'84Tractatus de septem sentimentis Christi Iesu\ldblquote  di Pietro di Giovanni Olivi, in: Pietro di Giovanni Olivi opera edita et inedita. Grottaferrata 1999, S. 533-550. \endash  Lit.: Petri Iohannis Olivi opera: Censimento dei manscritti, hrsg. von Antonio Ciceri. Grottaferrata/Roma 1999 (Collectio Oliviana 1), S. 248.}

