\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 65r-68r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Petrus Iohannes Olivi}}\plain \f1\b\lang1033\fs24\cf1 : Gradus amoris
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24\cf1 Modus aspirandi in deum et oraciones sancti Thome de Aquino et ad beatam virginem. \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 In nomine domini nostri Ihesu Christi amoris nostri crucifixi loquar tibi de aliquibus condicionibus et proprietatibus amoris dei \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 in eterno gaudio viuere valeamus praestante eodem domino nostro Ihesu Christo \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 Lit.: Giovanni Giacinto Sbaraglia, Supplementum et castigatio ad scriptores trium Ordinum s. Francisci, Bd. 2. Rom 1978, S. 344. \endash  Petri Iohannis Olivi opera (wie oben), S. 185.}

