\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 180r-186r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iohannes Gerson}}\plain \f1\b\lang1033\fs24 : De elucidatione scholastica mysticae theologiae
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberschrift Schwerzenbeck: \plain \f1\i\lang1033\fs24 Tractatus domini Iohannis de Gersona cancellarii Parisiensis de elucidacione mystice theologie sub xii consideracionibus\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Uobis datum est nosse misterium regni celorum dicebat Ihesus \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 theologie mistice consistentis in amore per Io\plain \f1\lang1033\fs24 [hannem] \plain \f1\i\lang1033\fs24 ca\plain \f1\lang1033\fs24 [ncellarium] \plain \f1\i\lang1033\fs24 Parisiensis\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 anno millesimo quadragentesimo vicesimo nono prima Iuni\plain \f1\lang1033\fs24 [i] [1429 Juni 1]. \endash  (180r) am oberen Seitenrand von anderer Hand Nota, teilweise beschnitten, mit der korrekten Datierung des Werkes auf das Jahr \plain \f1\i\lang1033\fs24 1424\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20 Edition:\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 Gerson, \u338 \'8cuvres compl\u232 \'e8tes VIII, S. 134-149 Nr. 421, zur Datierung S. XVIII. }

