\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 De sancto Hemerico filio sancti Stephani regis Vngarie\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Inclitus dux Hemericus ex illustri prosapia sicud cedrus ex Lybano \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 confessoris sui merita declarauit Ihesus Christus \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Amen. \endash  \plain \f1\lang1033\fs24\cf1 26v wegen durchgedr\u252 \'fcckter Tinte freigelassen.
