\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 74r-79v {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iohannes de Capestrano}}\plain \f1\b\lang1033\fs24 : Sermones
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (74r) \plain \f1\i\lang1033\fs24 In dominica post \plain \f1\lang1033\fs24 [festum] \plain \f1\i\lang1033\fs24 Inventionis de sancto dominico. In nomine patris \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 Amen. Iohannes de Capistrano \plain \f1\lang1033\fs24 [zu Beginn jedes Sermo Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24 Sermo fratris Iohannis Capistrani\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 Et quidem in hac die \plain \f1\lang1033\fs24 ... (Lc 19,42). \plain \f1\i\lang1033\fs24 Reverendi patres et domini verba sunt istius excellentissimi cancellarii immaculate virginis Marie matris \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (77r) \plain \f1\i\lang1033\fs24 Die martis. Et quidem in hac die \plain \f1\lang1033\fs24 ... (Lc 19,42). \plain \f1\i\lang1033\fs24 Reverendi patres et domini dictum de divisione et conditione sequitur consequenter quod dicendum sit \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (78v) \plain \f1\i\lang1033\fs24 Die mercurii ante Laurencii. In nomine patris \plain \f1\lang1033\fs24 ... \endash  \plain \f1\i\lang1033\fs24 Pax uobis \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (Io 20,19). \plain \f1\i\lang1033\fs24 Reverendi patres et domini verba sunt istius alti uolantis aquile Iohannis ewangeliste et sunt profluxa \plain \f1\lang1033\fs24 ... }

