\pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24 120r-195r {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Iohannes de Capestrano}}\plain \f1\b\lang1033\fs24 : Sermones
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 (120r) \plain \f1\i\lang1033\fs24 Ihesus. \plain \f1\lang1033\fs24 [Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24 Sermo vel quasi tractatulus fratris Iohannis Capistrani de libro vite ...\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Hec omnia liber vite \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (Sir 24,32). \plain \f1\i\lang1033\fs24 Inter omnes omnium gencium scripturas clementem et arcem tenuerunt diuinam scripturam \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 Amen. 1454\plain \f1\lang1033\fs24 . \endash  \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 (124v) \plain \f1\i\lang1033\fs24 Ihesus \plain \f1\lang1033\fs24 [zu allen Sermones Nachtrag Schwerzenbeck: \plain \f1\i\lang1033\fs24 Sermo fratris Iohannis Capistrani \plain \f1\lang1033\fs24 ...]. \plain \f1\i\lang1033\fs24 Quecumque scripta sunt \plain \f1\lang1033\fs24 ... (Rm 15,4). \plain \f1\i\lang1033\fs24 Liquide claret beatissime pater reuerendissimi domini et patres quoniam non modo me magnopere exalbescere \plain \f1\lang1033\fs24 ... \endash  \plain \f1\super\lang1033\fs24 3\plain \f1\lang1033\fs24 (128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sermo factus sabbato post festum corporis et sanguinis Christi\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Quocienscumque enim manducabit \plain \f1\lang1033\fs24 ... (1 Cor 11,26). \plain \f1\i\lang1033\fs24 Volens gloriosus appostolus Paulus indicare fidelibus memoriale perhenne domini nostri Ihesu Christi \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\super\lang1033\fs24 17\plain \f1\lang1033\fs24 (193r) \plain \f1\i\lang1033\fs24 Dominica infra octavas assumpcionis. In nomine patris ... Amen. Maria optimam partem \plain \f1\lang1033\fs24 ... (Lc 10,42). \plain \f1\i\lang1033\fs24 Reverendi patres et domini verba pro themate sumpta sunt ex ewangelio Luce summi cancellarii virginis Marie nichilominus sunt eciam domini nostri Ihesu Christi \plain \f1\lang1033\fs24 ...}

