\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Constituciones Gregorii pape noni\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Subscriptas constituciones edidit dominus Gregorius papa nonus et iussit eas in monasteriis sancti Bendictini\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 In primis ordinamus quod omnes monachi constituti \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 noluerint mox recedant. \plain \f1\lang1033\fs24\cf1 \endash  82v leer.
