\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 2r-37v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Sermones}}
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\super\lang1033\fs24\cf1 1\plain \f1\lang1033\fs24\cf1 (3r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Sermo de resurrectione domini ad religiosos\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Si consurrexistis cum Christo \plain \f1\lang1033\fs24\cf1 ... (Col 3,1). \plain \f1\i\lang1033\fs24\cf1 Non inmerito in hac dominice resurrectionis die fratres karissimi exultari nos hortatur \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 2\plain \f1\lang1033\fs24\cf1 (14r) \plain \f1\i\lang1033\fs24\cf1 Ascendit deus in iubilo \plain \f1\lang1033\fs24\cf1 ... (Ps 46,6). \plain \f1\i\lang1033\fs24\cf1 Quanta sit praesens festiuitas quantumque in ea Christianus gaudere debeat \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 3\plain \f1\lang1033\fs24\cf1 (18r) \plain \f1\i\lang1033\fs24\cf1 1447 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 In conuentu Mellicensi\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Cum complerentur dies \plain \f1\lang1033\fs24\cf1 ... (Act 2,1). \plain \f1\i\lang1033\fs24\cf1 Secundum magistrum sententiarum libro primo distinccione 14 duplex est processio \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 4\plain \f1\lang1033\fs24\cf1 (24r) \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Panem celi dedit eis \plain \f1\lang1033\fs24\cf1 ... (Ps 77,24)\u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Doctrina ut Ysidorus ait libro 3\plain \f1\i\super\lang1033\fs24\cf1 o\plain \f1\i\lang1033\fs24\cf1  de summo bono \plain \f1\lang1033\fs24\cf1 ... \endash  \plain \f1\super\lang1033\fs24\cf1 5\plain \f1\lang1033\fs24\cf1 (29v) \plain \f1\i\lang1033\fs24\cf1 Spiritus eius ornauit \plain \f1\lang1033\fs24\cf1 ... (Iob 26,3). \plain \f1\i\lang1033\fs24\cf1 Hodiernam venerandi prior ac fratres karissimi festiuitatem ut ait sanctus Leo papa in quodam sermone \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 laudetur deus in sublimis. M. K. 
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs20\cf1 1 = Johannes Staedler, baccalaureus formatus, Wien, in aula theologorum, vgl. Schneyer/H\u246 \'f6dl, Op.OSB Nr. 7. Auch in Clm 18638. \endash  2 = Thomas Ebendorfer, Sermones de tempore de evangeliis, pars aestivalis, mit abweichender Perikope (sonst: Mc 16,14). \endash  Alle Sermones auch in Melk, Benediktinerstift, Cod. 955 (12, A 14) (https://manuscripta.at/?ID=40653). }

