\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 126r-135v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Compendium contemplationis vitae heremiticae (1442}}\plain \f1\b\lang1033\fs24\cf1 )
\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\i\lang1033\fs24\cf1 Ihesus Christus. Conpendium \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 contemplationis super vita heremityca compilatum per quendam episcopum Cartusiensem in concilio Basiliensi. \plain \f1\lang1033\fs24\cf1 \endash  \plain \f1\i\lang1033\fs24\cf1 Super celestis consilii altitudo \plain \f1\lang1033\fs24\cf1 (!) \plain \f1\i\lang1033\fs24\cf1 qua cuncta termino sue perfectionis cinguntur vt vnaqueque res eodem claudatur termino \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 compendium contemplationis vite heremitice. Amen. M. M. Cor. die idus aprilis \plain \f1\lang1033\fs24\cf1 [April 13] \plain \f1\i\lang1033\fs24\cf1 1442. }

