\par \pard\fi0\li0\ql\ri0\sb0\sa240\itap0 \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Temporibus Octauiani imperatoris \plain \f1\lang1033\fs24\cf1 ... \plain \f1\i\lang1033\fs24\cf1 Lentulus in Iudea praeses senatui populoque Romano misit epistolam cuius sunt hec verba\plain \f1\lang1033\fs24\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs24\cf1 Apparuit temporibus nostris et adhuc est homo magne virtutis \plain \f1\lang1033\fs24\cf1 ... \endash  ... \plain \f1\i\lang1033\fs24\cf1 speciosus inter filios hominum etc. \plain \f1\lang1033\fs24\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs24\cf1 Hec epistola in annalibus Romanorum comperta est\plain \f1\lang1033\fs24\cf1 \u8249 \'8b
